    const role = model.snapshot?.role;
    const roleText = local ? '你可独立完成本轮设置、操作和时间推进。' : role === 'observer' ? '当前为观察者，操作由组内其他成员完成。' : role === 'student' ? '你负责判断与派遣，组织者负责开始、推进和结束。' : '你负责设置条件、开始实验、推进时间与评阅。';
